const db = new PGLite({path: './data/pglite.db'});

async function init() { await db.query(`CREATE TABLE IF NOT EXISTS columns (id TEXT PRIMARY KEY, title TEXT NOT NULL, position INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS cards (id TEXT PRIMARY KEY, column_id TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE, text TEXT, position INTEGER NOT NULL, created_at TEXT DEFAULT (datetime('now','localtime')) );`); // seed columns if none
const res = await db.query(`SELECT COUNT(*) as count FROM columns`);
if (res[0].count === 0) {
 await db.query(`INSERT INTO columns (id, title, position) VALUES
 ('1','To Do',1),
 ('2','In Progress',2),
 ('3','Done',3);`);
}
}

exports.db = db; exports.ready = async ()=>{await init(); return db;};

