{"path": "backend/db.js", "content": "const { PGLite } = require('@electric-sql/pglite');
const path = require('path');

// Use relative path to store the db file in backend/data
const dbPath = path.join(__dirname, 'data', 'pglite.db');
const db = new PGLite({ path: dbPath });

async function init() {
  // Create tables if they don't exist
  await db.exec(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position INTEGER NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT NOT NULL REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT,
      position INTEGER NOT NULL,
      created_at TEXT DEFAULT (datetime('now','localtime'))
    );
  `);

  // Seed default columns if table empty
  const res = await db.get(`SELECT COUNT(*) as count FROM columns`);
  if (res.count === 0) {
    await db.exec(`
      INSERT INTO columns (id, title, position) VALUES
        ("1", "To Do", 1),
        ("2", "In Progress", 2),
        ("3", "Done", 3);
    `);
  }
}

exports.db = db;
exports.init = init;
"}

{"path": "backend/server.js", "content": "const express = require('express');
const cors = require('cors');
const { db, init } = require('./db');
const boardRoutes = require('./routes/board');
const cardsRoutes = require('./routes/cards');

const app = express();
app.use(cors());
app.use(express.json());
app.use('/api', boardRoutes);
app.use('/api', cardsRoutes);

// SSE support
let clients = [];
function broadcast(event, data) {
  const payload = `event: ${event}\n` + `data: ${JSON.stringify(data)}\n\n`;
  clients.forEach(res => res.write(payload));
}
app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');
  res.write('data: connected\n\n');
  clients.push(res);
  req.on('close', () => {
    clients = clients.filter(c => c !== res);
  });
});

const PORT = process.env.PORT || 3000;

init().then(() => {
  app.listen(PORT, () => {
    console.log(`Server listening on port ${PORT}`);
  });
  // Expose broadcast to routes
  require('./routes/common').setBroadcast(broadcast);
});
"}

{"path": "backend/routes/common.js", "content": "let broadcastFn = null;
module.exports = {
  setBroadcast: (fn) => { broadcastFn = fn; },
  broadcast: (event, data) => {
    if (broadcastFn) broadcastFn(event, data);
  }
};
"}

{"path": "backend/routes/board.js", "content": "const express = require('express');
const { db } = require('../db');
const router = express.Router();

router.get('/board', async (req, res) => {
  try {
    const columns = await db.all('SELECT * FROM columns ORDER BY position ASC');
    const colMap = {};
    columns.forEach(col => { col.cards = []; colMap[col.id] = col; });
    const cards = await db.all('SELECT * FROM cards ORDER BY column_id, position ASC');
    cards.forEach(card => {
      const col = colMap[card.column_id];
      if (col) col.cards.push(card);
    });
    res.json(columns);
  } catch (err) {
    console.error(err);
    res.status(500).json({error: err.message});
  }
});

module.exports = router;
"}

{"path": "backend/routes/cards.js", "content": "const express = require('express');
const { db } = require('../db');
const { broadcast } = require('./common');
const router = express.Router();
const crypto = require('crypto');

function getNextPosition(columnId) {
  return db.get(`SELECT MAX(position) as maxPos FROM cards WHERE column_id = ?`, [columnId])
    .then(r => (r.maxPos !== null ? r.maxPos + 1 : 1));
}

router.post('/cards', async (req, res) => {
  const { columnId, text } = req.body;
  if (!columnId) return res.status(400).json({error: 'columnId required'});
  try {
    const id = crypto.randomUUID();
    const pos = await getNextPosition(columnId);
    await db.run('INSERT INTO cards (id, column_id, text, position) VALUES (?, ?, ?, ?)', [id, columnId, text, pos]);
    const card = { id, column_id: columnId, text, position: pos };
    broadcast('create', card);
    res.status(201).json(card);
  } catch (err) {
    console.error(err);
    res.status(500).json({error: err.message});
  }
});

router.patch('/cards/:id/move', async (req, res) => {
  const { id } = req.params;
  const { columnId: newColumnId, beforeId, afterId } = req.body;
  if (!newColumnId) return res.status(400).json({error: 'columnId required'});
  try {
    // Fetch card
    const card = await db.get('SELECT * FROM cards WHERE id = ?', [id]);
    if (!card) return res.status(404).json({error: 'Card not found'});
    // Determine new positions
    let beforePos = null;
    let afterPos = null;
    if (beforeId) {
      const before = await db.get('SELECT position FROM cards WHERE id = ?', [beforeId]);
      beforePos = before.position;
    }
    if (afterId) {
      const after = await db.get('SELECT position FROM cards WHERE id = ?', [afterId]);
      afterPos = after.position;
    }
    let newPos;
    if (beforePos !== null && afterPos !== null) {
      newPos = (beforePos + afterPos) / 2;
    } else if (beforePos !== null) {
      newPos = beforePos - 0.5;
    } else if (afterPos !== null) {
      newPos = afterPos + 0.5;
    } else {
      // empty column
      newPos = await getNextPosition(newColumnId);
    }
    // Update card
    await db.run('UPDATE cards SET column_id = ?, position = ? WHERE id = ?', [newColumnId, newPos, id]);
    const updatedCard = { ...card, column_id: newColumnId, position: newPos };
    broadcast('move', updatedCard);
    res.json(updatedCard);
  } catch (err) {
    console.error(err);
    res.status(500).json({error: err.message});
  }
});

module.exports = router;
"}

